// ========== 1. 本地消息表：业务操作和消息写入同一事务 ==========
@Service
public class OrderService {
    @Autowired private OrderRepo orderRepo;
    @Autowired private OutboxRepo outboxRepo;

    @Transactional
    public void createOrder(CreateOrderRequest req) {
        // 业务操作
        Order order = new Order(req);
        orderRepo.save(order);

        // 同一事务写入 Outbox 表
        OutboxMessage msg = new OutboxMessage();
        msg.setMessageId(UUID.randomUUID().toString());
        msg.setTopic("order-created");
        msg.setPayload(JSON.toJSONString(order));
        msg.setStatus("PENDING");
        msg.setCreatedAt(Instant.now());
        outboxRepo.save(msg);
    }
}

// ========== 2. 后台任务轮询 Outbox 并投递 ==========
@Component
public class OutboxRelay {
    @Scheduled(fixedDelay = 1000)
    public void pollAndSend() {
        List<OutboxMessage> pending = outboxRepo
            .findByStatus("PENDING", 100);
        for (OutboxMessage msg : pending) {
            try {
                SendResult result = producer.send(
                    new Message(msg.getTopic(), msg.getPayload())
                );
                if (result.getSendStatus() == SendStatus.SEND_OK) {
                    msg.setStatus("SENT");
                    outboxRepo.update(msg);
                }
            } catch (Exception e) {
                msg.setRetryCount(msg.getRetryCount() + 1);
                if (msg.getRetryCount() >= 5) {
                    msg.setStatus("FAILED"); // 超过重试上限，人工介入
                }
                outboxRepo.update(msg);
            }
        }
    }
}

// ========== 3. 幂等消费：Redis 快速过滤 + 数据库约束兜底 ==========
@Component
public class OrderConsumer {
    private static final String DEDUP_PREFIX = "mq:dedup:";
    private static final long DEDUP_TTL_HOURS = 24;

    @Autowired private RedisTemplate<String, String> redis;
    @Autowired private ProcessedMsgRepo processedRepo;

    @RocketMQListener(topic = "order-created")
    public void onMessage(OrderCreatedEvent event) {
        String dedupKey = DEDUP_PREFIX + event.getMessageId();

        // 第一层：Redis 快速去重
        Boolean isNew = redis.opsForValue()
            .setIfAbsent(dedupKey, "1",
                Duration.ofHours(DEDUP_TTL_HOURS));
        if (Boolean.FALSE.equals(isNew)) {
            return; // 已处理，跳过
        }

        try {
            // 第二层：数据库唯一约束兜底
            processedRepo.save(
                new ProcessedMessage(event.getMessageId())
            );
            // 业务处理
            processOrder(event);
        } catch (DuplicateKeyException e) {
            // 唯一约束冲突：重复消息，安全忽略
            return;
        } catch (Exception e) {
            // 业务异常：删除 Redis 标记，允许重试
            redis.delete(dedupKey);
            throw e; // 不 ACK，触发 Broker 重试
        }
    }
}

// ========== 4. 顺序消息：按订单 ID 分区 ==========
public void sendOrderEvent(String orderId, OrderEvent event) {
    producer.send(
        new Message("order-events", JSON.toJSONString(event)),
        (mqs, msg, arg) -> {
            String key = (String) arg;
            int index = Math.abs(key.hashCode()) % mqs.size();
            return mqs.get(index);
        },
        orderId // 分区 key
    );
}
